/bin/zsh -lc "git diff --check && node --input-type=module <<'JS'
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
const kb = JSON.parse(readFileSync('server/kristy_perimeter_kb.json', 'utf8'));
const before = JSON.parse(execFileSync('git', ['show', 'HEAD:server/kristy_perimeter_kb.json'], { maxBuffer: 64 << 20 }));
const ids = ['potato_chips', 'tortilla_chips', 'crackers', 'frozen_fries', 'frozen_nuggets', 'snack_bars', 'popcorn'];
const pinText = readFileSync('server/test/acceptance/twoLinePin.js', 'utf8');
const start = pinText.indexOf('export const TWO_LINE = ') + 'export const TWO_LINE = '.length;
const pins = JSON.parse(pinText.slice(start, pinText.indexOf('\\n};', start) + 2));
const skip = 'Seed oils to skip: sunflower, safflower, canola, soybean, corn, and cottonseed.';
const texts = v => typeof v === 'string' ? [v] : Array.isArray(v) ? v.flatMap(texts) : v && typeof v === 'object' ? Object.values(v).flatMap(texts) : [];
const changed = [];
for (const old of before.entries) {
  const entry = kb.entries.find(e => e.id === old.id);
  assert.ok(entry, old.id);
  if ("'!ids.includes(old.id)) { assert.deepEqual(entry, old); continue; }
  assert.deepEqual(entry.sources.slice(0, old.sources.length), old.sources);
  assert.ok(entry.buying_tips.includes(skip), `${entry.id} G7`);
  for (const tip of old.watch_out) assert.ok(entry.watch_out.includes(tip), `${entry.id} retained caution`);
  for (const field of ['"'aliases', 'asked_as', 'category', 'evidence_tier', 'why', 'short_answer', 'science', 'labels_decoded']) assert.deepEqual(entry[field], old[field], "'`${entry.id}.${field}`);
  for (const [field, value] of Object.entries(entry)) {
    if (JSON.stringify(value) !== JSON.stringify(old[field])) {
      assert.deepEqual(pins[entry.id][field], value, `${entry.id}.${field} unpinned`);
      changed.push(`${entry.id}.${field}`);
    }
  }
  const spoken = Object.fromEntries(Object.entries(entry).filter(([field]) => !['"'sources', 'aliases', 'asked_as', 'id', 'category', 'evidence_tier'].includes(field)));
  assert.doesNotMatch(texts(spoken).join(' '), /—|\\b(oxidation|omega[- ]?6|harms?|toxic\\w*|inflam\\w*)\\b/i, entry.id);
}
assert.equal(kb.entries.length, before.entries.length);
const snack = kb.entries.find(e => e.id === 'snack_bars');
const oldSnack = before.entries.find(e => e.id === 'snack_bars');
for (const field of ['decision', 'cart_pick', 'pick_steps', 'kristy_take', 'tier_note']) assert.deepEqual(snack[field], oldSnack[field], "'`snack_bars.${field}`);
console.log(`Scope/preservation audit passed: exactly ${ids.length} cards, ${changed.length} changed fields all pinned; existing sources and item-specific facts retained.`);
console.log(execFileSync('"'git', ['diff', '--name-only'], { encoding: 'utf8' }));
JS"
